69	// Validate the lone-ELF positional shape the standalone models require: print
70	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
71	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
72	// spawns a --describe subprocess per Verilator build). `model` labels the error.
73	int check_one_elf(const Cli& cli, const char* model) {
74	  if (cli.positional.empty()) {
75	    std::fprintf(stderr,
76	                 "andesim run --mode %s: missing ELF (the workload to run; "
77	                 "e.g. a tests/fixtures/<name>.elf)\n",
78	                 model);
79	    return 2;
80	  }
81	  if (cli.positional.size() > 1) {
82	    std::fprintf(stderr,
83	                 "andesim run --mode %s: unexpected argument '%s' "
84	                 "(engine args go after --)\n",
85	                 model, cli.positional[1].c_str());
86	    return 2;
87	  }
88	  return 0;
89	}
