229	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
230	// its --jtag-port only after it has reset and halted the hart, so the debugger we
231	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
232	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
233	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
234	// single debugger slot). Returns false on timeout.
235	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
236	  constexpr int kPollMs = 50;
237	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
238	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
239	      char line[512];
240	      while (std::fgets(line, sizeof line, f)) {
241	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
242	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
243	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
244	        unsigned lport = 0, st = 0;
245	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
246	            && st == 0x0A && lport == port) {
247	          std::fclose(f);
248	          return true;
249	        }
250	      }
251	      std::fclose(f);
252	    }
253	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
254	  }
255	  return false;
256	}
