310	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
311	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
312	// engine's own output. Unlike fast, this must discover the Verilator build(s)
313	// to resolve the engine (explicit --engine, else the sole one).
314	int run_accurate(const Cli& cli) {
315	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
316	  // --describe subprocess per Verilator build only to fail on the argument.
317	  if (int rc = check_one_elf(cli, "cycle")) return rc;
318	  // --mem-size is validated but has nothing to size: the cycle engine always
319	  // models its full DRAM window. Say so instead of silently ignoring it.
320	  if (!cli.mem_size.empty()) {
321	    std::string se;
322	    if (parse_size(cli.mem_size, se); !se.empty()) {
323	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
324	                   se.c_str());
325	      return 2;
326	    }
327	    std::fprintf(stderr,
328	                 "[andesim] --mem-size: the cycle engine models its full "
329	                 "DRAM window; nothing to size\n");
330	  }
331	  Discovery disc = discover_engines();
332	  std::string err;
333	  const EngineDescriptor* eng =
334	      resolve_accurate_engine(disc.engines, cli.engine, err);
335	  if (!eng) {
336	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
337	    // Surface why an expected engine may be absent (failed --describe, etc.).
338	    for (const std::string& w : disc.warnings)
339	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
340	    return 2;
341	  }
342	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
343	  // vice versa) cannot run. Catch it here with a clear message instead of the
344	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
345	  // positional.
346	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
347	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
348	    return 2;
349	  }
350	  // --dry-run previews the standalone command and spawns nothing, so it takes
351	  // precedence over the interactive --gdb path (a dry run launches no debugger).
352	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
353	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
354	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
355	  // monitor/gdbstub are interactive).
356	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
357	}
358	
359	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
360	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
361	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
362	// driver's tests/e2e.sh delegation with a single window-cycle line.
363	int run_hybrid(const Cli& cli) {
364	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
365	  auto fail = [](const std::string& msg) {
366	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
367	    return 2;
368	  };
369	
370	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
371	
372	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
373	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
374	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
375	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
376	  if (elf_path.empty()) return 2;
377	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
378	
379	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
380	  // mistake fails fast without spawning a --describe per Verilator build.
381	  std::string err;
382	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
383	  if (!err.empty()) return fail(err);
384	
385	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
386	  // hybrid triggers; unknown returned an error above) -- exactly the entry
387	  // boundary --verify needs the oracle to arm on.
388	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
389	  if (!err.empty()) return fail(err);
390	
391	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
392	  if (!cli.mem_size.empty()) {
393	    std::string se;
394	    mem = parse_size(cli.mem_size, se);
395	    if (!se.empty()) return fail("--mem-size: " + se);
396	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
397	    // guest RAM here. The physical mmap reserves one V-scratch page above the
398	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
399	    // page. Failing now beats allocating a huge mmap file first and letting
400	    // QEMU die late.
401	    if (mem > max_program_mem_bytes())
402	      return fail("--mem-size " + cli.mem_size +
403	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
404	                  "reservation)");
405	  }
406	
407	  // L26/F3: refuse a run whose static image would extend into the reserved
408	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
409	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
410	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
411	  // scratch -> silent corruption. Derive the page's start from
412	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
413	  // `mem`, so the threshold tracks the reservation shape instead of relying on
414	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
415	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
416	  // reports it.
417	  {
418	    std::string e;
419	    const uint64_t top = elf_load_top(elf_path, e);
420	    const uint64_t scratch_gpa =
421	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
422	    if (e.empty() && top > scratch_gpa) {
423	      char msg[256];
424	      std::snprintf(msg, sizeof(msg),
425	                    "ELF static image ends at 0x%llx, overlapping the reserved "
426	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
427	                    "; raise --mem-size or shrink the image",
428	                    static_cast<unsigned long long>(top),
429	                    static_cast<unsigned long long>(scratch_gpa));
430	      return fail(msg);
431	    }
432	  }
433	
434	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
435	  // or the sole cycle-accurate engine (reusing the F8 selector).
436	  Discovery disc = discover_engines();
437	  const EngineDescriptor* acc =
438	      resolve_accurate_engine(disc.engines, cli.engine, err);
439	  if (!acc) {
440	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
441	    for (const std::string& w : disc.warnings)
442	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
443	    return 2;
444	  }
445	
446	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
447	  // cannot share architectural state with the rv64 fast leg).
448	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
449	  // ...and the ELF must match that engine width too (same guard as cycle).
450	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
451	    return fail(e);
452	
453	  Plan plan;
454	  plan.elf = elf_path;
455	  plan.mem_size = mem;
456	  Step qemu_step{kQemuId64, "fast-leg", trig};
457	  Step vsim_step{acc->id, "accurate-leg", trig};
458	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
459	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
460	  // the accurate leg to drain just the counters and skip the full register-file
461	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
462	  // oracle diff sees every field. Driver policy lives here next to the rest of
463	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
464	  if (!cli.verify)
465	    vsim_step.extra_args.push_back("--drain-minimal");
466	  plan.steps = {qemu_step, vsim_step};
467	
468	  // Banner to stderr so the window-cycle result stands alone on stdout.
469	  // vlen is the synced value the fast leg inherits from the engine.
470	  std::fprintf(stderr,
471	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
472	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
473	               elf.stem().string().c_str());
474	
475	  PlanOptions opts;
476	  opts.dry_run = cli.dry_run;
477	  const PlanResult r = run_plan(plan, disc.engines, opts);
478	  if (!r.ok()) {
479	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
480	    return 1;
481	  }
482	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
483	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
484	  // then the vsim accurate leg -- and stop. Nothing was spawned.
485	  if (cli.dry_run) {
486	    std::vector<std::string> labels;
487	    labels.reserve(plan.steps.size());
488	    for (const Step& s : plan.steps)
489	      labels.push_back(s.role + " [" + s.engine_id + "]");
490	    return print_dry_run(r.argvs, labels);
491	  }
492	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
493	  // then anything the ROI wrote on vsim) belong to the user. The vsim
494	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
495	  // Version) -- strip it so only real program output shows, the same as `cycle`
496	  // does; its [info] log is already absent (the leg's stderr was dropped at
497	  // capture). The QEMU leg has no banner, so it relays verbatim.
498	  for (size_t i = 0; i < r.phases.size(); ++i) {
499	    const std::string& out = r.phases[i].out;
500	    if (out.empty()) continue;
501	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
502	      const std::string shown = strip_vsim_banner(out);
503	      std::fwrite(shown.data(), 1, shown.size(), stdout);
504	    } else {
505	      std::fwrite(out.data(), 1, out.size(), stdout);
506	    }
507	  }
508	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
509	  // vsim mcycle delta.
510	  {
511	    const unsigned long long q_mc = r.phases[0].mcycle;
512	    const unsigned long long v_mc = r.phases[1].mcycle;
513	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
514	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
515	  }
516	
517	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
518	  // config CSRs the program actually wrote; any of them this engine does not
519	  // implement would TRAP on its silicon (the program would never reach the
520	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
521	  // not represent this engine running this program.
522	  {
523	    const std::string w = unsupported_written_warning(
524	        r.phases[0].st, acc->andes_csrs, acc->id);
525	    if (!w.empty()) std::fputs(w.c_str(), stderr);
526	  }
527	
528	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
529	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
530	  // halt pc, and diff the two drains in-process. The oracle plan gets its
531	  // own fresh mmap: reusing the main run's would boot the oracle on the
532	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
533	  // output was already relayed from the main run.
534	  if (cli.verify) {
535	    char pcbuf[32];
536	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
537	                  static_cast<unsigned long long>(r.phases[1].st.pc));
538	    Trigger vtrig;
539	    vtrig.kind = "verify-" + trig.kind;
540	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
541	    vtrig.params["drain_pc"] = pcbuf;
542	
543	    Plan vplan;
544	    vplan.elf = elf_path;
545	    vplan.mem_size = mem;
546	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
547	
548	    std::fprintf(stderr,
549	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
550	                 "exit, pc=%s)\n",
551	                 pcbuf);
552	    const PlanResult vr = run_plan(vplan, disc.engines);
553	    if (!vr.ok()) {
554	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
555	      return 1;
556	    }
557	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
558	    // engine does not implement (it never restored/re-read them; comparing
559	    // would false-diff). Mirrors the resume/drain gating in vsim.
560	    const DiffReport d =
561	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
562	    print_diff_report(d);
563	    if (!d.ok()) {
564	      std::fprintf(stderr,
565	                   "andesim run --verify: vsim drain diverges from the "
566	                   "QEMU oracle\n");
567	      return 1;
568	    }
569	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
570	  }
571	
572	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
573	              elf.stem().string().c_str());
574	  return 0;
575	}
