23	// Validate the lone-ELF positional shape the standalone models require: print
24	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
25	int check_one_elf(const Cli& cli, const char* model) {
26	  if (cli.positional.empty()) {
27	    std::fprintf(stderr,
28	                 "andesim run --mode %s: missing ELF (the workload to run; "
29	                 "e.g. a tests/fixtures/<name>.elf)\n",
30	                 model);
31	    return 2;
32	  }
33	  if (cli.positional.size() > 1) {
34	    std::fprintf(stderr,
35	                 "andesim run --mode %s: unexpected argument '%s' "
36	                 "(engine args go after --)\n",
37	                 model, cli.positional[1].c_str());
38	    return 2;
39	  }
40	  return 0;
41	}
42	
43	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
44	// then run the resolved engine standalone with the post-`--` args forwarded
45	// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
46	// console works unchanged) and propagating the exit code. The per-model engine
47	// + selection are resolved by the caller; `model` here only labels the
48	// positional diagnostics. This minimal slice does no ELF existence/arch
49	// validation (that lands with strict validation).
50	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
51	                   const char* model) {
52	  if (int rc = check_one_elf(cli, model)) return rc;
53	  std::string err;
54	  const std::vector<std::string> argv = passthrough_argv(
55	      eng, "standalone", cli.positional[0], cli.passthrough, err);
56	  if (!err.empty()) {
57	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
58	    return 2;
59	  }
60	  return exec_passthrough(argv);
61	}
62	
63	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
64	// the built-in qemu descriptor directly (no engine discovery -- fast needs only
65	// qemu, and discover_engines would spawn a --describe per Verilator build).
66	int run_fast(const Cli& cli) {
67	  // fast is QEMU-only; an explicit engine must name it.
68	  if (!cli.engine.empty() && cli.engine != "qemu") {
69	    std::fprintf(stderr,
70	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
71	                 cli.engine.c_str());
72	    return 2;
73	  }
74	  return run_standalone(cli, builtin_qemu(), "fast");
75	}
76	
77	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
78	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
79	// engine's own output. Unlike fast, this must discover the Verilator build(s)
80	// to resolve the engine (explicit --engine, else the sole one).
81	int run_accurate(const Cli& cli) {
82	  Discovery disc = discover_engines();
83	  std::string err;
84	  const EngineDescriptor* eng =
85	      resolve_accurate_engine(disc.engines, cli.engine, err);
86	  if (!eng) {
87	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
88	    // Surface why an expected engine may be absent (failed --describe, etc.).
89	    for (const std::string& w : disc.warnings)
90	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
91	    return 2;
92	  }
93	  return run_standalone(cli, *eng, "cycle");
94	}
