40	std::vector<std::vector<std::string>> plan_argvs(
41	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
42	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
43	  std::vector<std::vector<std::string>> out;
44	  out.reserve(plan.steps.size());
45	  std::string prev_state_out;  // empty for the cold first leg
46	
47	  for (size_t i = 0; i < plan.steps.size(); ++i) {
48	    const Step& step = plan.steps[i];
49	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
50	    if (!eng) {
51	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
52	            step.engine_id + "'";
53	      return {};
54	    }
55	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
56	    if (!tmpl) {
57	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
58	            "' has no invoke template for role '" + step.role + "'";
59	      return {};
60	    }
61	
62	    const std::string state_out = state_path(workdir, i);
63	    const std::map<std::string, std::string> m = {
64	        {"bin", eng->bin_path},
65	        {"elf", plan.elf},
66	        {"plugin", ctx.plugin_path},
67	        {"mmap", ctx.mmap_path},
68	        {"mmap_size", std::to_string(ctx.mem_size)},
69	        {"mmap_base", ctx.mmap_base},
70	        {"state_in", prev_state_out},
71	        {"state_out", state_out},
72	    };
73	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
74	    if (!err.empty()) {
75	      err = "plan step " + std::to_string(i) + ": " + err;
76	      return {};
77	    }
78	    out.push_back(std::move(argv));
79	    prev_state_out = state_out;
80	  }
81	  err.clear();
82	  return out;
83	}
84	
85	PlanResult run_plan(const Plan& plan,
86	                    const std::vector<EngineDescriptor>& engines,
87	                    const PlanOptions& opts) {
88	  PlanResult res;
89	  if (plan.steps.empty()) {
90	    res.error = "plan has no steps";
91	    return res;
92	  }
93	
94	  // A private dir for the per-leg drain files each leg writes via {state_out}.
95	  std::error_code ec;
96	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
97	  std::string tmpl = workdir.string();
98	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
99	  tbuf.push_back('\0');
100	  const char* made = ::mkdtemp(tbuf.data());
101	  if (!made) {
102	    res.error = "failed to create plan work dir";
103	    return res;
104	  }
105	  const std::string wd = made;
106	
107	  RuntimeCtx ctx;
108	  ctx.mmap_path = plan.mmap_path;  // caller-pinned; the mmap backing lands later
109	  ctx.mem_size = plan.mem_size;
110	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps "0x0"
111	
112	  std::string err;
113	  const std::vector<std::vector<std::string>> argvs =
114	      plan_argvs(plan, engines, wd, ctx, err);
115	  if (!err.empty()) {
116	    res.error = err;
117	  } else {
118	    for (size_t i = 0; i < argvs.size(); ++i) {
119	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
120	      if (r.spawn_failed) {
121	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
122	        break;
123	      }
124	      if (r.timed_out) {
125	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
126	                    std::to_string(opts.timeout_ms) + " ms";
127	        break;
128	      }
129	      if (r.rc != opts.expect_rc) {
130	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
131	                    std::to_string(opts.expect_rc) + ", got " +
132	                    std::to_string(r.rc);
133	        break;
134	      }
135	      // The per-leg mcycle/minstret readback rides in with the shared-mmap
136	      // backing + state-file reader (the hybrid feature); this single-phase
137	      // slice only proves each leg drained (exit == expect_rc).
138	      res.phases.push_back({});
139	    }
140	  }
141	
142	  fs::remove_all(wd, ec);
143	  return res;
144	}
