1	// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
2	// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
3	//
4	// A Plan is a list of Steps; each Step names an engine (by id, resolved against
5	// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
6	// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
7	// order, threads the drained hybrid_state_v1 file forward, and reports each
8	// leg's outcome. Under the no-QEMU2-handback design every F6 step drains, so
9	// the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg mcycle.
10	#ifndef ANDESIM_PLAN_HPP
11	#define ANDESIM_PLAN_HPP
12	
13	#include <map>
14	#include <string>
15	#include <vector>
16	
17	namespace andes_sim {
18	
19	// The ROI delimiter for a step. `kind` is marker|pc; `params` carries
20	// kind-specific values (e.g. enter_pc, exit_pc) that F9 maps onto trigger
21	// args. F6 only exercises the default marker case (no params).
22	struct Trigger {
23	  std::string kind;
24	  std::map<std::string, std::string> params;
25	};
26	
27	// One leg of a plan: which engine, which invoke role, under which trigger.
28	struct Step {
29	  std::string engine_id;  // "qemu" | "vsim:ax45mpv_premium"
30	  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
31	  Trigger trigger;
32	};
33	
34	// A whole hybrid run. Every step loads `elf` and shares one mmap (`mem_size`
35	// bytes at `mmap_path`) that survives across every leg so memory threads
36	// through.
37	struct Plan {
38	  std::string elf;          // path to the ELF every leg launches
39	  long long mem_size = 0;   // shared-mmap size in bytes
40	  std::string mmap_path;    // the shared-mmap file every leg maps
41	  std::vector<Step> steps;
42	};
43	
44	// What one drain step measured (read back from its state file).
45	struct PhaseResult {
46	  unsigned long long mcycle = 0;
47	  unsigned long long minstret = 0;
48	};
49	
50	// Aggregate outcome. `error` empty => every step matched its expected exit and
51	// drained; `phases` then holds one entry per step in order.
52	struct PlanResult {
53	  std::string error;
54	  std::vector<PhaseResult> phases;
55	  bool ok() const { return error.empty(); }
56	};
57	
58	}  // namespace andes_sim
59	
60	#endif  // ANDESIM_PLAN_HPP
