43	// Select the cycle-accurate engine for `run --mode cycle` from an
44	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
45	// to the sole cycle-accurate engine -- erroring if there are none or more than
46	// one (ambiguous). With `want_id` set, that engine must exist and be
47	// cycle-accurate. Returns nullptr and sets `err` (naming the available
48	// cycle-accurate ids) on any failure; the returned pointer aliases into
49	// `engines`, so it must outlive the result.
50	inline const EngineDescriptor* resolve_accurate_engine(
51	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
52	    std::string& err) {
53	  auto is_accurate = [](const EngineDescriptor& e) {
54	    return e.kind == "cycle-accurate";
55	  };
56	  auto accurate_ids = [&] {
57	    std::vector<std::string> ids;
58	    for (const EngineDescriptor& e : engines)
59	      if (is_accurate(e)) ids.push_back(e.id);
60	    return join(ids, ", ");
61	  };
62	
63	  if (!want_id.empty()) {  // explicit --engine
64	    for (const EngineDescriptor& e : engines) {
65	      if (e.id != want_id) continue;
66	      if (is_accurate(e)) return &e;
67	      err = "engine '" + want_id + "' is " +
68	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
69	            "; a cycle-accurate engine is required";
70	      return nullptr;
71	    }
72	    std::string have = accurate_ids();
73	    err = "no engine '" + want_id + "'" +
74	          (have.empty() ? " (no cycle-accurate engines found)"
75	                        : " (cycle-accurate engines: " + have + ")");
76	    return nullptr;
77	  }
78	
79	  // No --engine: default to the sole cycle-accurate engine.
80	  const EngineDescriptor* sole = nullptr;
81	  int n = 0;
82	  for (const EngineDescriptor& e : engines)
83	    if (is_accurate(e)) { sole = &e; ++n; }
84	  if (n == 1) return sole;
85	  if (n == 0)
86	    err = "model cycle: no cycle-accurate engine found "
87	          "(build one with: scripts/build_all.sh vsim)";
88	  else
89	    err = "model cycle: multiple cycle-accurate engines; select one with "
90	          "--engine (have: " + accurate_ids() + ")";
91	  return nullptr;
92	}
