95	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
96	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
97	// dedup or shown anywhere, so every downstream consumer (list / --engine /
98	// errors) speaks "vsim" and a user never sees "verilator". Any other backend
99	// (qemu, a drop-in alioth/sid) passes through untouched.
100	inline void normalize_engine_label(EngineDescriptor& d) {
101	  if (d.type == "verilator") d.type = "vsim";
102	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
103	  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
104	  // report it under their internal name "csr" via --describe. Speak the CLI's
105	  // vocabulary in list / doctor too, like verilator -> vsim above.
106	  for (std::string& t : d.triggers)
107	    if (t == "csr") t = "marker";
108	}
