// Reader for a drained hybrid_state_v1 file -- the C++ analog of
// orchestrator.abi.validate_state_file + hsim._read_state_mcycle. Header-only:
// it #includes the shared ABI directly, so mcycle/minstret/flags/vlenb are
// struct members with no hand-copied offsets.
#ifndef ANDESIM_STATE_HPP
#define ANDESIM_STATE_HPP

#include <cstdio>
#include <vector>
#include <string>

#include "hybrid/state_abi.h"

namespace andes_sim {

struct StateFile {
  hybrid_state_v1 st{};
  std::string error;  // empty => valid; non-empty describes the rejection
  bool ok() const { return error.empty(); }
};

// Read `path` and validate it (in order): byte size == sizeof(hybrid_state_v1),
// magic == HYBRID_STATE_MAGIC, version == HYBRID_STATE_VERSION. On any failure
// `error` is set and `st` is unspecified; otherwise `st` holds the full state.
inline StateFile read_state_file(const std::string& path) {
  StateFile r;
  std::FILE* f = std::fopen(path.c_str(), "rb");
  if (!f) {
    r.error = path + ": cannot open";
    return r;
  }
  std::fseek(f, 0, SEEK_END);
  const long sz = std::ftell(f);
  std::rewind(f);
  if (sz != static_cast<long>(sizeof(hybrid_state_v1))) {
    r.error = path + ": size " + std::to_string(sz) + " != expected " +
              std::to_string(sizeof(hybrid_state_v1));
    std::fclose(f);
    return r;
  }
  const size_t n = std::fread(&r.st, 1, sizeof(r.st), f);
  std::fclose(f);
  if (n != sizeof(r.st)) {
    r.error = path + ": short read";
    return r;
  }

  char buf[256];
  if (r.st.magic != HYBRID_STATE_MAGIC) {
    std::snprintf(buf, sizeof(buf), "%s: magic 0x%08x != expected 0x%08x",
                  path.c_str(), r.st.magic, HYBRID_STATE_MAGIC);
    r.error = buf;
    return r;
  }
  if (r.st.version != HYBRID_STATE_VERSION) {
    std::snprintf(buf, sizeof(buf), "%s: version %u != expected %u",
                  path.c_str(), r.st.version, HYBRID_STATE_VERSION);
    r.error = buf;
    return r;
  }
  return r;
}

}  // namespace andes_sim

#endif  // ANDESIM_STATE_HPP

// Shared-mmap allocation for andesim.
//
// The hybrid handoff needs a file-backed mmap both legs share, so QEMU1's guest
// memory survives into the vsim leg. This minimal slice backs it with a plain
// /dev/shm sparse file (mkstemp + truncate); the tiered backing-store resolver
// and the guest --mem-size plumbing land as the feature grows.
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <string>

namespace andes_sim {

// Allocate a sparse mmap file of `size` bytes under /dev/shm (mkstemp +
// truncate), print one "[hsim mmap] <size> bytes at <dir>" line, and return its
// path. On failure returns "" and sets `err`. The caller owns the file and must
// unlink it when done.
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDESIM_SHM_HPP

// Shared-mmap allocation -- plain /dev/shm backing. See shm.hpp.
#include "shm.hpp"

#include <cstdio>
#include <vector>

#include <unistd.h>

namespace andes_sim {

std::string allocate(long long size, std::string& err,
                     const std::string& prefix) {
  // The hybrid handoff shares the mmap between QEMU and vsim, so it must live on
  // a tmpfs both processes can map with MAP_SHARED -- /dev/shm.
  const std::string dir = "/dev/shm";
  std::string tmpl = dir + "/" + prefix + "XXXXXX";
  std::vector<char> buf(tmpl.begin(), tmpl.end());
  buf.push_back('\0');
  const int fd = mkstemp(buf.data());
  if (fd < 0) {
    err = "failed to create mmap file in " + dir;
    return "";
  }
  close(fd);
  const std::string path(buf.data());
  if (truncate(path.c_str(), size) != 0) {
    unlink(path.c_str());
    err = "failed to size mmap file " + path;
    return "";
  }
  std::printf("[hsim mmap] %lld bytes at %s\n", size, dir.c_str());
  std::fflush(stdout);
  err.clear();
  return path;
}

}  // namespace andes_sim

// The pure core of `run --mode hybrid`: turn the CLI selection into a Trigger.
//
// Split out from cmd_run.cpp so it is unit-testable without spawning qemu/vsim.
// This minimal slice handles the marker trigger; pc-boundary resolution against
// the ELF .symtab lands with the pc-trigger completion.
#ifndef ANDESIM_HYBRID_HPP
#define ANDESIM_HYBRID_HPP

#include <string>

#include "cli.hpp"
#include "plan.hpp"

namespace andes_sim {

// Build the ROI Trigger for a hybrid run from `cli`. --trigger is REQUIRED
// (marker|pc); marker carries no params. On a missing or unknown trigger returns
// a Trigger with empty kind and sets `err`. `elf` is unused for marker -- the
// pc-boundary resolver reads it once the pc trigger lands.
Trigger hybrid_trigger(const Cli& cli, const std::string& elf, std::string& err);

}  // namespace andes_sim

#endif  // ANDESIM_HYBRID_HPP

// See hybrid.hpp. Builds the ROI Trigger from the CLI (marker slice).
#include "hybrid.hpp"

namespace andes_sim {

Trigger hybrid_trigger(const Cli& cli, const std::string& /*elf*/,
                       std::string& err) {
  err.clear();
  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
  // to fall back to marker, which masked running an unmarked ELF (the fast leg
  // ran to completion instead of draining at the ROI, surfacing only as a
  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
  if (cli.trigger.empty()) {
    err = "--trigger marker|pc is required "
          "(the ROI delimiter; see 'andesim run --help')";
    return {};
  }
  const std::string kind = cli.trigger;

  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params

  // pc-boundary resolution against the ELF .symtab lands with the pc-trigger
  // completion; until then only marker is a known hybrid trigger.
  err = "unknown trigger '" + kind + "' (want marker|pc)";
  return {};
}

}  // namespace andes_sim

// Unit tests for hybrid_trigger (F9): CLI selection -> ROI Trigger. This is the
// marker slice -- pc-boundary resolution against a fixture's .symtab lands with
// the pc-trigger completion. Pure (no spawn). Plain assert-and-count harness.
#include <string>
#include <vector>

#include "cli.hpp"
#include "hybrid.hpp"
#include "plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;

namespace {
Cli mk(const std::vector<std::string>& args) { return parse_cli(args); }
}  // namespace

int main() {
  const std::string elf = "unused-for-marker.elf";  // marker ignores the ELF

  // --trigger is REQUIRED for hybrid: there is no silent marker default. (It
  // used to default to marker, which masked running an unmarked ELF -- the fast
  // leg then ran to completion instead of draining at the ROI boundary, and the
  // user only saw a cryptic "expected exit 200, got 0".)
  {
    std::string err;
    hybrid_trigger(mk({"run", "--mode", "hybrid"}), elf, err);
    CHECK(!err.empty());
    CHECK(err.find("--trigger") != std::string::npos);
  }

  // marker is a valid EXPLICIT choice (no params).
  {
    std::string err;
    Trigger t = hybrid_trigger(
        mk({"run", "--mode", "hybrid", "--trigger", "marker"}), elf, err);
    CHECK(err.empty());
    CHECK(t.kind == "marker");
    CHECK(t.params.empty());
  }

  // An unknown trigger is an error.
  {
    std::string err;
    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "bogus"}), elf,
                   err);
    CHECK(!err.empty());
  }

  // icount/simpoint were removed: they now report as unknown triggers, not a
  // silent marker fallback.
  {
    std::string err;
    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "icount"}), elf,
                   err);
    CHECK(!err.empty());
    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "simpoint"}),
                   elf, err);
    CHECK(!err.empty());
  }

  return andes_sim::test::report("hybrid");
}

// F6 integration acceptance: a real 2-step hybrid plan, end to end.
//
// Unlike plan_test.cpp (pure, fake descriptors), this discovers the real
// engines, builds a marker-trigger [qemu fast-leg -> vsim accurate-leg] plan on
// a fixture ELF, and runs it through run_plan -- spawning actual QEMU + vsim and
// threading the drained hybrid_state_v1 between them. It asserts the done-when:
// the plan succeeds and the vsim leg's mcycle exceeds the qemu leg's (vsim
// restores qemu's mcycle then counts real cycles, so the delta is the measured
// kernel's cycle count). There is no QEMU2 leg -- handback was removed.
//
// Requires built artifacts (qemu, vsim, plugin, the fixture) AND a vsim whose
// ABI matches the driver's -- until that lands the vsim leg rejects the resume,
// so this acceptance is expected to fail before the ABI is pinned to the vsim.
// Run by tests/andes_sim/test_andes_sim_f6.sh. ELF overridable via argv[1].
#include <cstdio>
#include <string>
#include <vector>

#include "engine_registry.hpp"
#include "plan.hpp"
#include "repo_root.hpp"
#include "run_plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;

int main(int argc, char** argv) {
  const std::string elf =
      argc > 1 ? std::string(argv[1])
               : (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf")
                     .string();

  const Discovery disc = discover_engines();

  // Pick the first cycle-accurate engine that can play the accurate leg.
  const EngineDescriptor* vsim = nullptr;
  for (const EngineDescriptor& e : disc.engines)
    if (e.kind == "cycle-accurate" && e.invoke_for("accurate-leg")) {
      vsim = &e;
      break;
    }
  CHECK(vsim != nullptr);
  if (!vsim) return andes_sim::test::report("plan-itest");

  std::printf("[f6-itest] elf=%s engine=%s\n", elf.c_str(), vsim->id.c_str());

  Plan plan;
  plan.elf = elf;
  plan.mem_size = 128LL * 1024 * 1024;  // shared program RAM
  plan.steps = {
      {"qemu", "fast-leg", {"marker", {}}},
      {vsim->id, "accurate-leg", {"marker", {}}},
  };

  const PlanResult r = run_plan(plan, disc.engines);
  if (!r.ok())
    std::fprintf(stderr, "[f6-itest] run_plan error: %s\n", r.error.c_str());
  CHECK(r.ok());
  CHECK(r.phases.size() == 2);

  if (r.phases.size() == 2) {
    const unsigned long long q = r.phases[0].mcycle;
    const unsigned long long v = r.phases[1].mcycle;
    std::printf(
        "[f6-itest] qemu1 mcycle=%llu  vsim mcycle=%llu  kernel_cycles=%llu\n",
        q, v, v - q);
    CHECK(v > q);  // vsim measured a non-empty ROI
    CHECK(r.phases[1].minstret >= r.phases[0].minstret);
  }

  return andes_sim::test::report("plan-itest");
}

